"""Pre-call semantic certificates from unchanged historical Q/R/Claims.

Task-directed coverage bank. No new Claims, hypothetical premises, model calls
or future evidence. ClaimSet subsets are experimental evidence presentations,
not fabricated historical states. Repeated locators/sets are correlated probes.
"""
from collections import Counter
from .common import *

CERT=[]
def add(cell,locator,ids,kind,reason,missing=None,risk=False,ambiguity=None,tags=()):
 CERT.append(dict(cell_id=cell,candidate_locator=locator,candidate_claim_ids=ids,category=kind,gold_verdict='SUBTRACTABLE' if kind=='positive' else 'NOT_SUBTRACTABLE',gold_reason=reason,gold_missing_semantics=missing,false_full_risk=risk,ambiguity_reason=ambiguity,case_tags=list(tags)))
def main():
 ss={s['cell_id']:s for s in read(P/'e0_reference/STATES.json')};parents={r['cell_id']:'\n'.join(x['text'] for x in r['parent']['source_spans']) for r in read(P/'e0_reference/PARENTS.json')}
 # Immutable selection/annotation list is completed before request construction.
 add('A01','Two people wrote it.',['C1'],'binding_missing','Professor identity does not establish target-paper authorship.','The candidate must be bound to an observed paper and its two-author relation.',tags=['candidate_identity'])
 add('A02','Two people wrote it.',['C2'],'positive','Explicit same-paper coauthorship by the two named authors establishes this clause. The Baltic-publication sentence remains independent and unresolved.',tags=['author_count'])
 add('A02','Two people wrote it.',['C1','C2'],'positive','C1 identifies the Harran candidate and C2 gives the concrete two-author article; C1 is a permitted redundant binding member.',tags=['author_count','claimset'])
 add('A02','Two people wrote it.',['C3','C4'],'background_irrelevant','Categories and tables do not give author count.','An observed two-author publication relation is absent.',tags=['background_control'])
 add('A03',parents['A03'],['C2','C4','C5'],'positive','Named article, its Emotion table and the percentage observation jointly establish the entire Parent.',tags=['table_percentage','claimset'])
 add('A03',parents['A03'],['C4','C5'],'positive','C4 names an observed paper D10 and its Emotion table; C5 gives the entry in that paper. The concrete observed paper/table branch is sufficient without proving other Parents.',tags=['table_percentage','claimset'])
 add('A03',parents['A03'],['C5'],'binding_missing','The percentage is locally stated but that paper has no antecedent in this supplied one-Claim packet.','Bind the table entry to a concrete observed paper; Q itself supplies no document identity.',risk=True,ambiguity='Whether an anaphoric Claim alone is treated as a self-contained source record. Primary reference requires its supplied antecedent, without consulting the withheld Claims.',tags=['table_percentage','claimset_ablation'])
 add('A04',parents['A04'],['C1','C2'],'qualifier_incomplete','Founder and degree facts do not establish the full games/university constraints.','The game release/ranking and university-founding qualifications remain unestablished.',risk=True,tags=['Kwon_Ding','qualifier_control'])
 add('A05','up to 2019, had no children from the marriage',['C1','C2'],'binding_missing','Founder identity and education supply no observed marital condition.','Observed marriage and childlessness through2019 on the same person branch.',tags=['Kwon_Ding'])
 add('A06','was part of a specific university',['C2'],'binding_missing','A person alma mater is not the building affiliation relation.','An identified building and its university affiliation.',tags=['alma_mater_building'])
 add('A07','who, up to 2019, had no children from the marriage',['C4','C5'],'positive','Ding founder identity plus same-person married/childless2019 statement establish the parenthetical marital condition. Gift/construction/complex remain unresolved; this does not close the Parent.',tags=['Kwon_Ding','Ding_marriage','claimset'])
 add('A07','who, up to 2019, had no children from the marriage',['C1','C3'],'qualifier_incomplete','Kwon family status in2025 does not establish the2019 childlessness condition.','The required temporal marital/childlessness condition, not a2025 family description.',tags=['Kwon_Ding','temporal_attachment'])
 add('A07',parents['A07'],['C4','C5'],'binding_missing','Ding marital support does not establish his joint gift or its construction/complex relation.','The same couple made the foundational gift for a building in a larger complex.',risk=True,tags=['Ding_marriage','whole_parent_control'])
 add('A08',parents['A08'],['C4','C5'],'binding_missing','Ding company, degree and marriage facts do not identify any building or opening/affiliation relation.','Bind a concrete building to its opening schedule and university.',risk=True,tags=['Kwon_Ding','alma_mater_building'])
 add('A09','shares their first name with part of a charity’s name',['C1'],'binding_missing','Artist identity alone leaves the charity/name relation absent.','An observed charity name related to this artist first name.',tags=['artist_charity'])
 add('A10','20 to 30 miles (inclusive) away',['C1'],'qualifier_incomplete','Death in Athens does not establish distance from the specified aviation-accident site.','The city-to-specified-accident-site distance and its governing site identity.',tags=['artist_distance'])
 add('A11','shares their first name with part of a charity’s name',['C2','C3'],'background_irrelevant','Partner and tribute facts are adjacent song context, not charity evidence.','The artist/charity name-sharing relation.',tags=['artist_charity','background_control'])
 add('A12','under the guidance of an Iranian professor',['C1','C2'],'binding_missing','Author and Canadian PhD study do not identify any advisor or establish Iranian nationality.','The observed advisor relation and the advisor Iranian qualification.',risk=True,tags=['advisor_relation'])
 add('A13','publishing the book',['C1'],'binding_missing','The locally true book publication is only an operand; no later article relation is observed in this packet.','Same-author later article connected to the book by the required topical and six-year relation.',tags=['book_article'])
 add('A14','publishing the book',['C1','C3'],'positive','Both observed publications, same author, aligned subjects and2016/2022 years establish the book operand in its complete article-comparison context.',tags=['book_article_positive','claimset'])
 add('A14','six years after publishing the book',['C1','C3'],'positive','Same-author article2022 follows the observed2016 book by six publication years.',ambiguity='Year-level interval rather than exact day-level elapsed duration; frozen inherited question/reference uses publication years.',tags=['book_article_positive','claimset','comparison'])
 add('A14','on a similar topic',['C1','C3'],'positive','Both publication subjects concern Vipassana and mathematics; their same-author article/book and six-publication-year relation is also supplied.',tags=['book_article_positive','claimset'])
 add('A14','six years after publishing the book',['C3'],'binding_missing','An article year alone cannot establish an article-to-book interval.','The same-author book publication operand and year for the comparison.',tags=['book_article','claimset_ablation'])
 add('A15','born in the early 1700s',['C1'],'binding_missing','Euler birth attributes are true locally but not bound to a person referenced by the target book.','The target book references Euler; his biography cannot supply that relation.',tags=['Euler'])
 add('A16','a half-year history of pain in different parts of their body',['C1','C2'],'background_irrelevant','Generic SPS symptoms/course do not establish this specific case history.','An observed individual case with the specified duration and clinical course.',tags=['generic_SPS','background_control'])
 clinical=parents['A17'].split('\n')[1]
 add('A17',clinical,['C7'],'positive','The concrete ten-year-old case directly records the complete clinical course. The country-history sentence is a separate unresolved obligation, not a prerequisite to knowing this case clinical history.',tags=['q637_clinical'])
 add('A17','a half-year history of pain in different parts of their body',['C7'],'positive','The case record supplies the six-month duration and locations, with the worsening/mobility context also explicitly present.',tags=['q637_clinical','locator_width'])
 add('A17','causing difficulty in walking and moving their shoulders',['C7'],'positive','The record supplies worsening pain and the resulting walking/shoulder limitation for this same individual.',tags=['q637_clinical','locator_width'])
 add('A17',parents['A17'].split('\n')[0],['C7'],'binding_missing','Pakistani patient nationality does not establish where the case was reported or the country historical predicate.','Bind the report to a country and establish its largest/dominant-religion status at founding.',risk=True,tags=['patient_nationality_report_country'])
 add('A17','a half-year history of pain in different parts of their body',['C10','C11'],'background_irrelevant','Even same-disorder molecular/trauma background does not establish this individual clinical course.','The observed individual case, specified symptom locations and six-month duration.',tags=['generic_FOP','background_control'])
 add('A18',parents['A18'],['C1','C2'],'background_irrelevant','A game thesis and its advisor do not establish a DLC release or game-release interval.','The DLC/base-game release relation and dates.',risk=True,tags=['background_control'])
 add('A19',parents['A19'],['C3','C5'],'positive','Same-game DLC October2016 and base release August2013, plus strategy genre, establish the entire requirement. Either August day yields more than three years.',tags=['DLC_release','claimset'])
 add('A19','over three years after its release',['C3','C5'],'positive','The bound two release events give the required >3-year comparison; neither operand is transferred to another game.',tags=['DLC_release','claimset','comparison'])
 add('A19','a strategy video game',['C3','C5'],'positive','The short genre locator inherits the DLC-to-game release relationship and interval, all supplied jointly by C3+C5.',tags=['DLC_release','claimset','locator_width'])
 add('A19',parents['A19'],['C3'],'qualifier_incomplete','DLC identity/date alone does not establish base-game genre and >3-year release comparison.','Base-game genre/release date establishing the comparison.',risk=True,tags=['DLC_release','claimset_ablation'])
 add('A20','religion and technology',['C3','C4'],'positive','C3 binds package to base game; C4 records technology changes and a new Coptic system. The separate nation-qualified mechanics conjunct stays unresolved.',tags=['DLC_mechanics_positive','claimset'])
 add('A20','technology',['C3','C6'],'positive','C3 binds DLC/game and C6 directly states the game technology was redone. Other mechanics and nation constraints remain unresolved.',tags=['DLC_mechanics_positive','claimset'])
 add('A20','made changes to the mechanics of the base game including religion and technology',['C3','C4','C6'],'positive','Bound package/manual/diary Claims establish both named kinds of change. This locator stops before the separately conjoined qualified-nation condition.',tags=['DLC_mechanics_positive','claimset'])
 add('A20','made changes to the mechanics of the base game',['C3','C7'],'positive','C3 binds the DLC and C7 establishes government/subject mechanics changes. This qualifies the general changes predicate only, not religion/technology particulars or playable-European-nation status.',ambiguity='General-predicate subtraction may be understood as retaining its unresolved specific qualifiers; primary reference licenses only the general changes fact, never those qualifiers.',tags=['DLC_mechanics_positive','claimset'])
 add('A20','new mechanics for a specific playable European nation',['C3','C4','C7'],'qualifier_incomplete','Ottoman changes/flavor do not explicitly establish the playable-European-nation qualification. No outside geography/playability facts are admitted.','The specific nation receiving new mechanics meets both playable and European qualifications.',risk=True,tags=['DLC_qualifier'])
 add('A20',parents['A20'],['C3','C4','C7'],'qualifier_incomplete','The ClaimSet supplies the general/technology/religious changes but not the qualified nation, so the whole Parent is not safely subtractable.','The playable-European-nation condition remains unresolved.',risk=True,tags=['DLC_qualifier','whole_parent_control'])
 add('A21',parents['A21'],['C1','C2'],'positive','Jerry nationality and the same Jerry champion-team membership/year jointly establish the whole condition.',tags=['champion_positive','claimset'])
 add('A21','an Australian coder',['C1','C2'],'positive','Nationality is linked to the coder on the champion team by C2; all governing membership/championship context is observed.',tags=['champion_positive','claimset'])
 add('A21','an Australian coder',['C1'],'binding_missing','Nationality alone cannot establish that this coder belongs to the champion team described in Parent.','The coder-to-winning-team membership and championship relation.',risk=True,tags=['champion_binding','claimset_ablation'])
 add('A22',parents['A22'],['C1','C2'],'binding_missing','Jerry nationality and teammate names leave the other-two same-country relation unestablished.','The two other teammates share a country with each other; Jerry nationality is insufficient.',risk=True,tags=['teammate_same_country'])
 add('A23',parents['A23'],['C1','C2'],'binding_missing','March5 dates the covering memorandum, not letter composition; no accession date exists.','The enclosed-letter writing date and same-author accession interval.',risk=True,tags=['memo_letter_date'])
 add('A24',parents['A24'],['C1','C3'],'positive','C1 identifies the letter/author and C3 supplies its country-region content.',tags=['letter_region_positive','claimset'])
 add('A24','their country having regained a region',['C2','C3'],'positive','Letter handover and content remain on the same King Michael/Romania branch; author attribution, letter and regained-region relation are supplied.',tags=['letter_region_positive','claimset'])
 assert len(CERT)==48 and sum(x['gold_verdict']=='SUBTRACTABLE' for x in CERT)==22
 seen=Counter();out=[]
 for c in CERT:
  cell=c['cell_id'];s=ss[cell];seen[cell]+=1;ids=c['candidate_claim_ids'];assert 1<=len(ids)<=3 and len(set(ids))==len(ids);assert c['candidate_locator'] in parents[cell]
  claims={x['claim_id']:x for x in s['claims']};assert set(ids)<=set(claims)
  out.append({'certificate_id':f'{cell}_CAND{seen[cell]}','case_id':s['case_id'],'qid':s['qid'],'parent_requirement_id':s['parent_requirement_id'],**c,'candidate_verified_claims':[claims[k] for k in ids],'original_question_sha256':digest(s['question']),'parent_sha256':digest(parents[cell]),'claims_sha256':digest([claims[k] for k in ids]),'reviewer':'Codex single task-familiar Q/R/ClaimSet reviewer; no new model calls'})
 assert set(seen)==set(ss)
 write(P/'e0_reference/CERTIFICATES.json',out)
 write(P/'e0_reference/BANK_COUNTS.json',{'certificates':48,'positive':22,'negative':26,'cells':24,'snapshots':len({s['case_id'] for s in ss.values()}),'qids':len({s['qid'] for s in ss.values()}),'categories':dict(Counter(c['category'] for c in out)),'claimset_sizes':dict(Counter(str(len(c['candidate_claim_ids'])) for c in out)),'false_full_risk_certificates':[c['certificate_id'] for c in out if c['false_full_risk']],'ambiguous_certificates':[c['certificate_id'] for c in out if c['ambiguity_reason']]})
 historical={n:sha(ROOT/n) for n in git('ls-files','experiments').splitlines() if not n.startswith(rel(P)+'/') and (ROOT/n).is_file()}
 write(P/'analysis/HISTORICAL_HASHES.json',historical)
 print(read(P/'e0_reference/BANK_COUNTS.json'))
if __name__=='__main__':main()
